import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.DCVnL8g5.js";const u=JSON.parse('{"title":"SSH: introduccion y claves","description":"","frontmatter":{},"headers":[],"relativePath":"devops/ssh/01-introduccion-y-claves.md","filePath":"devops/ssh/01-introduccion-y-claves.md","lastUpdated":1789040978000,"isDraft":false}'),o={name:"devops/ssh/01-introduccion-y-claves.md"};function r(l,a,n,d,c,p){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="ssh-introduccion-y-claves" tabindex="-1">SSH: introduccion y claves <a class="header-anchor" href="#ssh-introduccion-y-claves" aria-label="Permalink to &quot;SSH: introduccion y claves&quot;">​</a></h1><p>SSH (Secure Shell) es el protocolo estandar para administrar servidores Linux de forma remota con cifrado. Sustituye a Telnet y rsh: autentica, cifra el trafico y permite reenviar puertos, copiar archivos y ejecutar comandos sin exponer contrasenas en claro.</p><p>En la practica, casi todo el trabajo DevOps (despliegues, Ansible, Git sobre remoto, tunnels a bases de datos) pasa por SSH.</p><h2 id="capitulos" tabindex="-1">Capitulos <a class="header-anchor" href="#capitulos" aria-label="Permalink to &quot;Capitulos&quot;">​</a></h2><ol><li><a href="./01-introduccion-y-claves">Introduccion y claves</a></li><li><a href="./02-conexion-y-configuracion">Conexion y configuracion</a></li><li><a href="./03-agentes-y-forwarding">Agentes y forwarding</a></li><li><a href="./04-scp-sftp-y-tunnels">SCP SFTP y tunnels</a></li><li><a href="./05-hardening-del-servidor">Hardening del servidor</a></li><li><a href="./06-troubleshooting">Troubleshooting</a></li></ol><h2 id="que-problema-resuelve" tabindex="-1">Que problema resuelve <a class="header-anchor" href="#que-problema-resuelve" aria-label="Permalink to &quot;Que problema resuelve&quot;">​</a></h2><p>Sin SSH (o con solo contrasena):</p><ul><li>Credenciales reutilizadas y faciles de forcear.</li><li>Sesiones sin cifrado en redes no confiables.</li><li>Automatizacion fragil (prompts interactivos).</li></ul><p>Con claves SSH:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cliente (clave privada)  --&gt;  servidor (clave publica en authorized_keys)</span></span>
<span class="line"><span>         |                              |</span></span>
<span class="line"><span>         +-------- canal cifrado -------+</span></span></code></pre></div><h2 id="tipos-de-clave" tabindex="-1">Tipos de clave <a class="header-anchor" href="#tipos-de-clave" aria-label="Permalink to &quot;Tipos de clave&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tipo</th><th>Recomendacion</th><th>Notas</th></tr></thead><tbody><tr><td><strong>ed25519</strong></td><td>Preferida</td><td>Rapida, corta, segura</td></tr><tr><td><strong>ecdsa</strong></td><td>Aceptable</td><td>Menos habitual que ed25519</td></tr><tr><td><strong>rsa 4096</strong></td><td>Legado</td><td>Solo si un sistema antiguo no acepta ed25519</td></tr><tr><td><strong>dsa</strong></td><td>Evitar</td><td>Obsoleta e insegura</td></tr></tbody></table><h2 id="generar-un-par-de-claves" tabindex="-1">Generar un par de claves <a class="header-anchor" href="#generar-un-par-de-claves" aria-label="Permalink to &quot;Generar un par de claves&quot;">​</a></h2><p>En tu maquina local (no en el servidor):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tu-email@ejemplo.com&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519</span></span></code></pre></div><ul><li><code>-C</code> anade un comentario para identificar la clave.</li><li>Te pedira passphrase: usala. Protege la privada si el disco se filtra.</li><li>Resultado: <ul><li><code>~/.ssh/id_ed25519</code> — <strong>privada</strong> (nunca la copies a un repo).</li><li><code>~/.ssh/id_ed25519.pub</code> — <strong>publica</strong> (va al servidor).</li></ul></li></ul><p>Ver la publica:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519.pub</span></span></code></pre></div><h2 id="instalar-la-clave-en-el-servidor" tabindex="-1">Instalar la clave en el servidor <a class="header-anchor" href="#instalar-la-clave-en-el-servidor" aria-label="Permalink to &quot;Instalar la clave en el servidor&quot;">​</a></h2><p>Opcion recomendada:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-copy-id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519.pub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usuario@servidor.ejemplo.com</span></span></code></pre></div><p>Manual (si no tienes <code>ssh-copy-id</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usuario@servidor.ejemplo.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;mkdir -p ~/.ssh &amp;&amp; chmod 700 ~/.ssh&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519.pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usuario@servidor.ejemplo.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;cat &gt;&gt; ~/.ssh/authorized_keys &amp;&amp; chmod 600 ~/.ssh/authorized_keys&quot;</span></span></code></pre></div><p>Permisos tipicos que exige <code>sshd</code>:</p><table tabindex="0"><thead><tr><th>Ruta</th><th>Modo</th></tr></thead><tbody><tr><td><code>~/.ssh</code></td><td><code>700</code></td></tr><tr><td><code>~/.ssh/authorized_keys</code></td><td><code>600</code></td></tr><tr><td>clave privada</td><td><code>600</code></td></tr></tbody></table><h2 id="primera-conexion" tabindex="-1">Primera conexion <a class="header-anchor" href="#primera-conexion" aria-label="Permalink to &quot;Primera conexion&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usuario@servidor.ejemplo.com</span></span></code></pre></div><p>La primera vez veras el fingerprint del host. Verificalo (out-of-band) antes de aceptar; queda guardado en <code>~/.ssh/known_hosts</code>.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Subir la clave <strong>privada</strong> al servidor o a GitHub.</li><li>Usar RSA 1024 o DSA &quot;porque siempre se uso&quot;.</li><li>Dejar <code>authorized_keys</code> con <code>777</code> (sshd ignora la clave).</li><li>Generar la clave en el servidor y bajarte solo la publica (flujo invertido e incomodo).</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas practicas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas practicas&quot;">​</a></h2><ul><li>Una clave por maquina o por proposito (trabajo, personal, CI).</li><li>Passphrase en la privada + agente SSH (capitulo 3).</li><li>Rotar claves si un portatil se pierde.</li><li>Preferir ed25519 salvo incompatibilidad real.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Genera una clave ed25519 con comentario identificable.</li><li>Copia la publica a un servidor de prueba (o a un contenedor con <code>sshd</code>).</li><li>Conecta sin contrasena y comprueba <code>echo $USER</code> en remoto.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continua con <a href="./02-conexion-y-configuracion">Conexion y configuracion</a>.</p>`,36)])])}const k=e(o,[["render",r]]);export{u as __pageData,k as default};
